"use client";

import * as React from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Smartphone, ArrowRight, Shield, Zap } from "lucide-react";
import { PhoneInput } from "@/components/auth/PhoneInput";
import { createClient } from "@/utils/supabase/client";
import { cn } from "@/lib/utils";

export default function LoginPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const redirect = searchParams.get("redirect") || "/";

  const [phone, setPhone] = React.useState("");
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (!phone || phone.length < 10) {
      setError("Please enter a valid phone number.");
      return;
    }

    setIsLoading(true);
    try {
      const supabase = createClient();
      const { error: otpError } = await supabase.auth.signInWithOtp({
        phone,
        options: { channel: "sms" },
      });

      if (otpError) {
        setError(otpError.message);
        return;
      }

      // Store phone and redirect in sessionStorage for verify-otp page
      sessionStorage.setItem("rl_auth_phone", phone);
      sessionStorage.setItem("rl_auth_redirect", redirect);
      router.push("/auth/verify-otp?mode=login");
    } catch {
      setError("Something went wrong. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-8">
      {/* Card */}
      <div className="bg-card/60 backdrop-blur-xl border border-border/40 rounded-2xl p-8 shadow-2xl shadow-black/20">
        {/* Icon + Title */}
        <div className="text-center space-y-3 mb-8">
          <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl bg-primary/10 border border-primary/20 mb-2">
            <Smartphone className="w-7 h-7 text-primary" />
          </div>
          <h1 className="text-2xl font-black tracking-tight">Welcome back</h1>
          <p className="text-muted-foreground text-sm leading-relaxed">
            Enter your mobile number to receive a secure OTP.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">
          <PhoneInput
            value={phone}
            onChange={setPhone}
            disabled={isLoading}
            error={error}
            placeholder="Enter mobile number"
          />

          <button
            type="submit"
            disabled={isLoading || !phone}
            className={cn(
              "w-full flex items-center justify-center gap-2 py-3.5 rounded-xl font-bold text-sm transition-all duration-200",
              "bg-primary text-primary-foreground hover:bg-primary/90 active:scale-[0.98]",
              "shadow-lg shadow-primary/25 hover:shadow-primary/40",
              isLoading || !phone ? "opacity-60 cursor-not-allowed" : ""
            )}
          >
            {isLoading ? (
              <>
                <div className="w-4 h-4 border-2 border-primary-foreground border-t-transparent rounded-full animate-spin" />
                Sending OTP...
              </>
            ) : (
              <>
                Send OTP
                <ArrowRight className="w-4 h-4" />
              </>
            )}
          </button>
        </form>

        <div className="mt-6 pt-5 border-t border-border/30 text-center">
          <p className="text-xs text-muted-foreground">
            New to Ranker&apos;s League?{" "}
            <Link href="/auth/register" className="text-primary font-bold hover:underline">
              Create Account
            </Link>
          </p>
        </div>
      </div>

      {/* Trust badges */}
      <div className="grid grid-cols-2 gap-3">
        {[
          { icon: Shield, text: "256-bit encrypted", sub: "End-to-end secure" },
          { icon: Zap, text: "OTP in < 10 sec", sub: "Instant delivery" },
        ].map(({ icon: Icon, text, sub }) => (
          <div key={text} className="flex items-center gap-2.5 bg-card/30 backdrop-blur-sm border border-border/30 rounded-xl px-4 py-3">
            <Icon className="w-4 h-4 text-primary shrink-0" />
            <div>
              <p className="text-[11px] font-bold text-foreground">{text}</p>
              <p className="text-[10px] text-muted-foreground">{sub}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
